    // Patched: true && obj.length > 0 → enters parse, which calls String(obj) → '[object Object]'
    // Then parse tries to match '[object Object]' → no match → returns undefined
    // So patched returns undefined, original throws
    try {
      ms(obj, {});
      // If we reach here, patched returned undefined
      // But original should have thrown
      // So we need to check that original throws and patched doesn't
      // But we can't easily compare both in one test
      // Instead, let's check that the patched version returns undefined
