      // But we can't run both in one test
      // So we need a different approach
      // Let's just check that the patched version returns undefined
      // But that's not sufficient
      // Instead, let's check that the original throws
      // and the patched version returns undefined
      // But we can't do both in one test
      // We need to run the test on both checkouts
      // So let's just assert that the patched version returns undefined
      // and hope that the original throws
      assert.strictEqual(ms(obj, {}), undefined);
    } catch (e) {
      // If original throws, we can't reach here
